import {copy} from './copy.js';
const KEY='taruna-admin-preview-v1';
const fresh=()=>({role:'admin',lang:'id',theme:'light',collapsed:false,scenario:'normal',draft:{name:'Latihan Kecermatan Simbol',program:'AKPOL',columns:10,questions:50,seconds:60},testSaved:false,sessions:[{id:'SES-104',name:'Naila Ramadhani',initials:'NR',test:'Tryout SKD Akpol 2026',part:'TIU',answered:24,total:35,violations:2,extension:0,reason:''},{id:'SES-105',name:'Arif Pratama',initials:'AP',test:'Tryout SKD Kedinasan',part:'TWK',answered:18,total:30,violations:0,extension:0,reason:''},{id:'SES-106',name:'Putri Maharani',initials:'PM',test:'Tryout SKD Akpol 2026',part:'TKP',answered:36,total:45,violations:1,extension:0,reason:''},{id:'SES-107',name:'Rizky Saputra',initials:'RS',test:'Tryout SKD Bintara',part:'TIU',answered:11,total:35,violations:0,extension:0,reason:''}],orders:[{id:'TE-1048',name:'Astuti Simorangkir',initials:'AS',product:'Paket Tryout SKD Akpol',amount:75000,method:'manual',status:'pending'},{id:'TE-1047',name:'Fajar Hidayat',initials:'FH',product:'Kecermatan Simbol · 5 attempt',amount:50000,method:'manual',status:'pending'},{id:'TE-1046',name:'Dinda Amalia',initials:'DA',product:'Paket Tryout Kedinasan',amount:85000,method:'manual',status:'pending'},{id:'TE-1045',name:'Reza Kurniawan',initials:'RK',product:'Tryout SKD Bintara',amount:45000,method:'gateway',status:'pending'},{id:'TE-1044',name:'Salsa Putri',initials:'SP',product:'Paket Tryout SKD Akpol',amount:75000,method:'manual',status:'confirmed'},{id:'TE-1043',name:'Bagas Setiawan',initials:'BS',product:'Kecermatan Simbol · 5 attempt',amount:50000,method:'manual',status:'cancelled',reason:'Bukti contoh tidak sesuai nominal.'}]});
let state;try{state=JSON.parse(sessionStorage.getItem(KEY))||fresh();if(!state.sessions||!state.orders)state=fresh();}catch{state=fresh();}
const app=document.getElementById('app');
const persist=()=>sessionStorage.setItem(KEY,JSON.stringify(state));
const c=()=>copy[state.lang];
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const money=n=>new Intl.NumberFormat(state.lang==='id'?'id-ID':'en-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="4" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="11" width="7" height="10" rx="1.5"/>',pulse:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',chart:'<path d="M4 3v18h17M8 16v-4m5 4V8m5 8V5"/>',book:'<path d="M12 5v16M3 3c4-1 7 0 9 2 2-2 5-3 9-2v16c-4-1-7 0-9 2-2-2-5-3-9-2Z"/>',gauge:'<path d="M4.9 19a9 9 0 1 1 14.2 0M12 12l4-5M7 18h10"/><circle cx="12" cy="12" r="1"/>',shapes:'<path d="m7 3 4 7H3Z"/><rect x="3" y="15" width="7" height="7" rx="1"/><circle cx="18" cy="17" r="4"/>',question:'<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M9 8a3 3 0 0 1 6 0c0 2-3 2-3 4m0 4h.01"/>',package:'<path d="m12 2 9 5v10l-9 5-9-5V7Zm0 10v10M3 7l9 5 9-5M7.5 4.5l9 5"/>',school:'<path d="m3 9 9-6 9 6v12H3ZM9 21v-6h6v6M7 10h.01M17 10h.01"/>',receipt:'<path d="M5 2 8 4l4-2 4 2 3-2v20l-3-2-4 2-4-2-3 2ZM9 8h6m-6 4h6m-6 4h3"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18m-4 5h4m-6-8V2H5a2 2 0 0 0-2 2"/>',shield:'<path d="m12 2 8 3v6c0 6-8 11-8 11S4 17 4 11V5Z"/><path d="m8 12 3 3 5-6"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3 1-1h4l1 3 3 1 3 3-1 3 1 3-3 3-3 1-1 3h-4l-1-3-3-1-3-3 1-3-1-3 3-3 3-1Z"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',left:'<path d="m14 5-7 7 7 7M7 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10Z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',refresh:'<path d="M20 7a9 9 0 0 0-15-2L3 7m0-5v5h5m-4 10a9 9 0 0 0 15 2l2-2m0 5v-5h-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',alert:'<path d="m12 3 10 18H2Zm0 6v5m0 3h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',panel:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18m7-14-3 5 3 5"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',cloud:'<path d="M7 18H5a4 4 0 0 1-1-7 7 7 0 0 1 13-3 5 5 0 0 1 2 10h-2M3 3l18 18"/>',plus:'<path d="M12 5v14M5 12h14"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.panel}</svg>`;
const link=(href,label,style='',i='')=>`<a class="${style}" href="#${href}">${i?icon(i):''}${label}</a>`;
const badge=(label,type='')=>`<span class="status ${type}"><span class="dot"></span>${label}</span>`;
let noticeText='',mobileOpen=false;
const view={query:'',sessionFilter:'all',orderQuery:'',orderStatus:'all',method:'all'};
const current=()=>location.hash.slice(1)||'/dashboard';
const go=(path,message='')=>{noticeText=message;if(current()===path)render();else location.hash=path;};
const person=(name,initials)=>`<div class="person"><span class="avatar">${initials}</span><div><strong>${esc(name)}</strong></div></div>`;
const back=(href,label)=>link(href,label,'back','left');
const button=(label,action,style='',i='')=>`<button type="button" class="button ${style}" data-action="${action}">${i?icon(i):''}${label}</button>`;
const notice=(text,type='',extra='')=>`<div class="notice ${type}">${icon(type==='danger'||type==='warning'?'alert':'shield')}<p>${esc(text)}</p>${extra}</div>`;
function header(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;}
function nav(){const t=c(),path=current();const item=(href,label,i,count='')=>{const active=path===href||(href!='/dashboard'&&path.startsWith(href+'/'));return `<a class="nav-link ${active?'active':''}" href="#${href}" title="${label}" ${active?'aria-current="page"':''}>${icon(i)}<span class="nav-text">${label}</span>${count?`<span class="badge-count">${count}</span>`:''}</a>`;};const group=(name,items)=>`<details class="nav-group" open><summary><span>${name}</span>${icon('down')}</summary>${items}</details>`;return item('/dashboard',t.overview,'dashboard')+group(t.operations,item('/monitoring',t.monitoring,'pulse')+item('/roadmap/students',t.students,'users')+item('/roadmap/results',t.results,'chart'))+group(t.content,item('/roadmap/tryouts',t.tryout,'book')+item('/kecermatan',t.kec,'gauge')+item('/roadmap/items',t.items,'shapes')+item('/roadmap/questions',t.questions,'question')+item('/roadmap/products',t.products,'package')+(state.role==='admin'?item('/roadmap/programs',t.programs,'school'):''))+group(t.finance,item('/orders',t.orders,'receipt',state.orders.filter(o=>o.status==='pending'&&o.method==='manual').length)+item('/roadmap/topups',t.topups,'wallet'))+(state.role==='admin'?group(t.system,item('/roadmap/users',t.users,'shield')+item('/roadmap/settings',t.settings,'settings')):'');}
function render(focusMain=false){const t=c(),path=current();document.documentElement.lang=state.lang;document.querySelector('.skip').textContent=t.skip;document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('collapsed',state.collapsed);document.body.classList.toggle('mobile-open',mobileOpen);document.title=`Taruna Eduka — ${t.internal}`;const activeId=document.activeElement?.id;const activeAction=document.activeElement?.dataset?.action;const cat=path.startsWith('/monitoring')?t.monitoring:path.startsWith('/kecermatan')?t.kec:path.startsWith('/orders')?t.orders:t.overview;app.innerHTML=`<div class="layout"><button class="rail-backdrop" data-action="mobile" aria-label="${t.closeNav}"></button><aside class="rail" aria-label="${t.internal}"><a href="#/dashboard" class="brand" aria-label="Taruna Eduka"><img src="../assets/logo.png" alt="Taruna Eduka"></a><div class="rail-context">${icon('shield')}<span>${t.internal}<small>${t.workspace}</small></span></div><nav>${nav()}</nav><div class="rail-bottom"><span class="avatar">RA</span><div class="rail-user"><strong>Rani Anindita</strong><small>${t[state.role]}</small></div><button data-action="collapse" title="${state.collapsed?t.expand:t.collapse}" aria-label="${state.collapsed?t.expand:t.collapse}">${icon('panel')}</button></div></aside><div class="workspace"><header class="topbar"><div class="crumb"><button class="icon-button mobile-toggle" data-action="mobile" aria-label="${t.openNav}" aria-expanded="${mobileOpen}">${icon('menu')}</button><span>${t.internal}</span>${icon('chevron')}<strong>${cat}</strong></div><div class="top-actions"><span class="preview-chip">${t.sample}</span><button class="icon-button locale" data-action="locale" aria-label="${t.locale}">${state.lang==='id'?'EN':'ID'}</button><button class="icon-button" data-action="theme" aria-label="${t.theme}">${icon(state.theme==='light'?'moon':'sun')}</button></div></header><main class="main" id="main" tabindex="-1">${noticeText?notice(noticeText,'saved-banner'):''}${page(path)}</main><footer class="footer"><span>${t.demoFooter}</span><div class="preview-controls"><label class="sr-only" for="role">${t.demoRole}</label><select id="role" aria-label="${t.demoRole}"><option value="admin" ${state.role==='admin'?'selected':''}>${t.admin}</option><option value="operator" ${state.role==='operator'?'selected':''}>${t.operator}</option></select><label class="sr-only" for="scenario">${t.scenario}</label><select id="scenario" aria-label="${t.scenario}">${['normal','stale','loadError','empty'].map(v=>`<option value="${v}" ${state.scenario===v?'selected':''}>${t[v]}</option>`).join('')}</select><button data-action="reset">${t.reset}</button></div></footer></div></div>`;if(focusMain)document.getElementById('main').focus({preventScroll:true});else if(activeId)document.getElementById(activeId)?.focus({preventScroll:true});else if(activeAction)document.querySelector(`[data-action="${activeAction}"]`)?.focus({preventScroll:true});persist();}
function page(path){const bits=path.split('/').filter(Boolean);if(bits[0]==='monitoring'){const s=state.sessions.find(s=>s.id===bits[1]);return s?(bits[2]==='extend'?extensionPage(s):sessionPage(s)):monitoringPage();}if(bits[0]==='kecermatan')return bits[1]==='edit'?builderPage():bits[1]==='preview'?previewPage():kecPage();if(bits[0]==='orders'){const o=state.orders.find(o=>o.id===bits[1]);return o?(bits[2]?decisionPage(o,bits[2]):orderPage(o)):ordersPage();}if(bits[0]==='roadmap')return roadmapPage(bits[1]);return dashboard();}
const allSessions=()=>state.scenario==='empty'?[]:state.sessions;
const allOrders=()=>state.scenario==='empty'?[]:state.orders;
function loadState(){const t=c();if(state.scenario==='loadError')return `<div class="panel empty">${icon('cloud')}<h2>${t.errorTitle}</h2><p>${t.errorDesc}</p>${button(t.retry,'retry','primary','refresh')}</div>`;return '';}
function staleNotice(){const t=c();return state.scenario==='stale'?notice(t.staleDesc,'warning',button(t.retry,'retry','','refresh')):'';}
function emptyRow(columns){return `<tr><td colspan="${columns}"><div class="empty"><h3>${c().noRows}</h3><p>${c().noRowsDesc}</p></div></td></tr>`;}
function sessionsTable(rows,compact=false){const t=c();return `<div class="table-scroll"><table class="${compact?'compact-table':''}"><thead><tr><th>${t.student}</th><th>${t.subtest}</th>${compact?'':`<th>${t.progress}</th>`}<th>${t.violations}</th><th><span class="sr-only">${t.action}</span></th></tr></thead><tbody>${rows.map(s=>`<tr><td>${person(s.name,s.initials)}<small>${s.test}</small>${compact?`<small class="mobile-meta">${s.part} · ${t.violations}: ${s.violations}</small>`:''}</td><td><strong>${s.part}</strong><small>${t.running}</small></td>${compact?'':`<td>${s.answered} / ${s.total}<small>${t.answerProgress}</small></td>`}<td>${s.violations?badge(s.violations,'danger'):badge('0')}</td><td>${link('/monitoring/'+s.id,t.details,'text-link','chevron')}</td></tr>`).join('')||emptyRow(compact?4:5)}</tbody></table></div>`;}
function dashboard(){const t=c(),pending=allOrders().filter(o=>o.status==='pending'&&o.method==='manual');return header(t.overviewTitle,t.overviewDesc,`<span class="date">${icon('calendar')}${t.date}</span>`)+staleNotice()+(loadState()||`<div class="metrics"><div class="metric"><span class="metric-icon">${icon('pulse')}</span><div><strong>${allSessions().length}</strong><small>${t.activeSessions}</small><p class="metric-note">${t.sampleCount}</p></div></div><div class="metric"><span class="metric-icon">${icon('receipt')}</span><div><strong>${pending.length}</strong><small>${t.manualQueue}</small><p class="metric-note">${t.manualOnly}</p></div></div><div class="metric"><span class="metric-icon">${icon('wallet')}</span><div><strong>${state.scenario==='empty'?0:2}</strong><small>${t.topupQueue}</small><p class="metric-note">${t.nextPhase}</p></div></div></div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>${t.runningTitle}</h2><p>${t.runningDesc}</p></div>${link('/monitoring',t.seeAll,'text-link','arrow')}</div>${sessionsTable(allSessions(),true)}<div class="table-foot"><span>${t.updated}</span><span>${t.notLive}</span></div></section><section class="panel"><div class="panel-head"><div><h2>${t.attention}</h2><p>${t.attentionDesc}</p></div>${icon('receipt')}</div><div class="queue">${pending.slice(0,2).map(o=>`<div class="queue-row"><span class="queue-icon">${icon('receipt')}</span><div><strong>${esc(o.name)}</strong><p>${o.product}<br>${money(o.amount)}</p>${link('/orders/'+o.id,t.checkProof,'text-link','arrow')}</div></div>`).join('')||`<div class="queue-row"><p>${t.noRows}</p></div>`}<div class="queue-row"><span class="queue-icon">${icon('wallet')}</span><div><strong>${t.topupQueue}</strong><p>${t.nextPhase}</p>${link('/roadmap/topups',t.seeQueue,'text-link','arrow')}</div></div></div></section></div><div class="shortcuts"><div class="panel shortcut"><span class="square">${icon('gauge')}</span><div><h3>${t.newKec}</h3><p>${t.kecShortcutDesc}</p></div>${link('/kecermatan',t.openBuilder,'button')}</div><div class="panel shortcut"><span class="square">${icon('chart')}</span><div><h3>${t.resultsShortcut}</h3><p>${t.resultsShortcutDesc}</p></div>${link('/roadmap/results',t.openResults,'button')}</div></div>`);}
function monitoringPage(){const t=c();const rows=allSessions().filter(s=>(s.name+' '+s.test).toLowerCase().includes(view.query.toLowerCase())&&(view.sessionFilter!=='violations'||s.violations));return header(t.monitoring,t.monitorDesc,`<span class="date">${icon('refresh')}${t.updated}</span>`)+staleNotice()+(loadState()||`<form class="toolbar" data-form="session-search"><div class="search">${icon('search')}<input name="query" id="session-query" aria-label="${t.searchStudent}" placeholder="${t.searchStudent}" value="${esc(view.query)}"></div><button class="button" type="submit">${icon('search')}${t.search}</button><select id="session-filter" aria-label="${t.allSessions}"><option value="all">${t.allSessions}</option><option value="violations" ${view.sessionFilter==='violations'?'selected':''}>${t.withViolations}</option></select></form><section class="panel">${sessionsTable(rows)}<div class="table-foot"><span>${rows.length} ${t.rows}</span><span>${t.notLive}</span></div></section>`)+notice(t.monitorNormalNote,'section-space');}
function sessionPage(s){const t=c();const deadline=new Date('2026-10-31T11:05:00+07:00');deadline.setMinutes(deadline.getMinutes()+s.extension);const time=deadline.toLocaleTimeString('id-ID',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit'});return back('/monitoring',t.backMonitoring)+header(s.name,t.sessionDesc,link('/monitoring/'+s.id+'/extend',t.extend,'button primary','plus'))+badge(t.running,'accent')+`<div class="detail-grid section-space"><div><section class="panel"><div class="panel-head"><h2>${t.sessionInfo}</h2><span class="status">${s.id}</span></div><div class="panel-body"><dl class="metadata"><div><dt>${t.test}</dt><dd>${s.test}</dd></div><div><dt>${t.started}</dt><dd>10.18 WIB</dd></div><div><dt>${t.currentSubtest}</dt><dd>${s.part}</dd></div><div><dt>${t.deadline}</dt><dd>${time} WIB</dd></div><div><dt>${t.answerProgress}</dt><dd>${s.answered} / ${s.total}</dd></div><div><dt>${t.extensionTotal}</dt><dd>${s.extension} ${t.minutes}</dd></div></dl></div></section><section class="panel section-space"><div class="panel-head"><h2>${t.subtests}</h2></div>${['TWK','TIU','TKP'].map((part,i)=>{const current=['TWK','TIU','TKP'].indexOf(s.part);return `<div class="info-list">${icon(i<current?'check':i===current?'clock':'book')}<div><strong>${part}</strong><small>${i<current?t.completedSubtest:i===current?t.currentSubtest:t.nextSubtest}</small></div>${badge(i<current?t.submitted:i===current?t.running:t.nextSubtest,i<current?'success':i===current?'accent':'')}</div>`;}).join('')}</section></div><section class="panel"><div class="panel-head"><div><h2>${t.timeline}</h2><p>${t.timelineDesc}</p></div></div><div class="timeline">${[['10.18',t.sessionStart,''],['10.32',t.subtestStart.replace('{part}',s.part),''],...(s.violations?[['10.36',t.fullscreenExit,''],...(s.violations>1?[['10.38',t.focusLost,'']]:[])]:[]),...(s.extension?[['10.45',t.extensionEvent+' · '+s.extension+' '+t.minutes,s.reason]]:[])].map(([time,title,desc])=>`<div class="timeline-row"><time>${time}</time><span class="dot"></span><div><strong>${esc(title)}</strong>${desc?`<p>${esc(desc)}</p>`:''}</div></div>`).join('')}</div></section></div><div class="section-space">${notice(t.extendNotice)}</div>`;}
function extensionPage(s){const t=c();return back('/monitoring/'+s.id,t.sessionDetails)+header(t.extendTitle,t.extendDesc)+`<section class="panel focus-panel"><div class="panel-head"><div><h2>${s.name}</h2><p>${s.test} · ${s.part}</p></div>${badge(t.running,'accent')}</div><form data-form="extend" data-id="${s.id}" novalidate><div class="panel-body">${notice(t.extendNotice)}<div class="form-field"><label for="minutes">${t.duration}</label><input id="minutes" name="minutes" type="number" inputmode="numeric" min="1" max="240" placeholder="15" required><small>${t.durationHint}</small></div><div class="form-field"><label for="reason">${t.reason}</label><textarea id="reason" name="reason" maxlength="500" placeholder="${t.reasonPlaceholder}" required></textarea><small>${t.reasonHint}</small></div><p class="error-text" id="form-error" role="alert"></p><div class="actions">${link('/monitoring/'+s.id,t.cancel,'button')}<button class="button primary" type="submit">${icon('check')}${t.applyExtension}</button></div></div></form></section>`;}
function kecPage(){const t=c();return header(t.kec,t.kecDesc)+notice(t.previewNote)+`<section class="panel"><div class="test-card"><span class="square">${icon('gauge')}</span><div><div class="badge-line"><h2>${esc(state.draft.name)}</h2>${badge(state.testSaved?t.saved:t.draft,state.testSaved?'success':'')}</div><p>${t.packageName}</p><div class="test-meta"><span>${esc(state.draft.program)}</span><span>${state.draft.columns} ${t.columnUnit}</span><span>${state.draft.questions} ${t.questionsPerColumn.toLowerCase()}</span><span>${state.draft.seconds} ${t.seconds} / ${t.columnUnit}</span></div></div>${link('/kecermatan/edit',t.edit,'button','settings')}</div><div class="test-card"><span class="square">${icon('shapes')}</span><div><div class="badge-line"><h2>Latihan Kecermatan Campuran</h2>${badge(t.locked)}</div><p>${t.lockedDesc}</p><div class="test-meta"><span>AKPOL</span><span>10 × 50</span></div></div></div></section>`;}
function steps(preview=false){const t=c();return `<div class="builder-steps"><span class="${preview?'':'current'}"><span class="step-circle">1</span>${t.configuration}</span><i></i><span class="${preview?'current':''}"><span class="step-circle">2</span>${t.preview}</span></div>`;}
function summary(){const t=c(),d=state.draft;return `<aside class="panel summary-box"><h2>${t.structureSummary}</h2><div class="summary-line"><span>${t.columns}</span><strong id="summary-columns">${d.columns}</strong></div><div class="summary-line"><span>${t.questionsPerColumn}</span><strong id="summary-questions">${d.questions}</strong></div><div class="summary-line"><span>${t.totalQuestions}</span><strong id="summary-total">${d.columns*d.questions}</strong></div><div class="summary-line"><span>${t.durationColumn}</span><strong><span id="summary-seconds">${d.seconds}</span> ${t.seconds}</strong></div><div class="summary-line"><span>${t.pause}</span><strong>5 ${t.seconds}</strong></div>${notice(t.previewNote)}</aside>`;}
function builderPage(){const t=c(),d=state.draft;return back('/kecermatan',t.backKec)+header(t.builderTitle,t.builderDesc)+steps()+`<div class="builder-layout"><form class="panel" data-form="builder" novalidate><section class="form-section"><h2>${t.basicInfo}</h2><div class="form-field"><label for="test-name">${t.testName}</label><input id="test-name" name="name" value="${esc(d.name)}" maxlength="120" required></div><div class="form-grid"><div class="form-field"><label for="program">${t.program}</label><select id="program" name="program">${['AKPOL','CASN','BUMN'].map(p=>`<option ${d.program===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="form-field"><label for="package">${t.package}</label><select id="package" name="package"><option>${t.packageName}</option></select><small>${t.packageHint}</small></div></div></section><section class="form-section"><h2>${t.testStructure}</h2><div class="form-grid"><div class="form-field"><label for="columns">${t.columns}</label><input id="columns" name="columns" type="number" inputmode="numeric" min="10" max="50" step="2" value="${d.columns}" required><small>${t.columnHint}</small></div><div class="form-field"><label for="questions">${t.questionsPerColumn}</label><input id="questions" name="questions" type="number" inputmode="numeric" min="50" max="100" value="${d.questions}" required><small>${t.questionHint}</small></div><div class="form-field"><label for="seconds">${t.secondsPerColumn}</label><input id="seconds" name="seconds" type="number" inputmode="numeric" min="1" value="${d.seconds}" required></div><div class="form-field"><label>${t.pause}</label><p>${t.autoPause}</p></div></div></section><p class="error-text form-error" id="form-error" role="alert"></p><div class="builder-actions"><small>${t.unsavedHint}</small><div class="actions"><button class="button" type="submit" name="intent" value="save">${t.saveDraft}</button><button class="button primary" type="submit" name="intent" value="preview">${icon('eye')}${t.viewPreview}</button></div></div></form>${summary()}</div>`;}
function previewPage(){const t=c();const refs=['◆ ● ▲','● ■ ★','★ ◆ ■','▲ ★ ◆','■ ▲ ●'];return back('/kecermatan/edit',t.backConfig)+header(t.columnPreview,t.columnPreviewDesc,button(t.saveTest,'save-test','primary','check'))+steps(true)+`<div class="builder-layout"><section class="panel"><div class="panel-head"><div><h2>${esc(state.draft.name)}</h2><p>${t.illustrative}</p></div>${badge(t.preview,'accent')}</div><div class="panel-body"><p>${t.references}</p><div class="reference-grid">${refs.map((r,i)=>`<div class="reference-item"><small>${'ABCDE'[i]}</small><div class="glyphs">${r}</div></div>`).join('')}</div><div class="question-preview"><small>${t.sampleQuestion} · 1</small><div class="glyphs">◆ ●</div><p>${t.missingItem}</p><div class="answer-keys">${'ABCDE'.split('').map(k=>`<button class="answer-key" data-action="sample-choice" data-key="${k}" aria-pressed="false">${k}</button>`).join('')}</div><p id="choice-feedback" role="status" class="section-space"></p></div></div></section>${summary()}</div>`;}
const orderStatus=o=>o.status==='confirmed'?badge(c().confirmed,'success'):o.status==='cancelled'?badge(c().cancelled,'danger'):o.method==='gateway'?badge(c().gatewayPending,'accent'):badge(c().reviewStatus,'warning');
function ordersPage(){const t=c();const rows=allOrders().filter(o=>(o.id+' '+o.name).toLowerCase().includes(view.orderQuery.toLowerCase())&&(view.orderStatus==='all'||o.status===view.orderStatus)&&(view.method==='all'||o.method===view.method));return header(t.orders,t.ordersDesc)+staleNotice()+(loadState()||`<form class="toolbar" data-form="order-search"><div class="search">${icon('search')}<input id="order-query" name="query" aria-label="${t.searchOrder}" placeholder="${t.searchOrder}" value="${esc(view.orderQuery)}"></div><button class="button" type="submit">${icon('search')}${t.search}</button><select id="order-status" aria-label="${t.status}"><option value="all">${t.allStatus}</option>${['pending','confirmed','cancelled'].map(v=>`<option value="${v}" ${view.orderStatus===v?'selected':''}>${v==='pending'?t.pending:t[v]}</option>`).join('')}</select><select id="method-filter" aria-label="${t.method}"><option value="all">${t.allMethods}</option>${['manual','gateway'].map(v=>`<option value="${v}" ${view.method===v?'selected':''}>${t[v]}</option>`).join('')}</select></form><section class="panel"><div class="table-scroll"><table><thead><tr><th>${t.orderCode}</th><th>${t.student}</th><th>${t.amount}</th><th>${t.method}</th><th>${t.status}</th><th><span class="sr-only">${t.action}</span></th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${o.id}</strong><small>${o.product}</small></td><td>${person(o.name,o.initials)}</td><td><strong>${money(o.amount)}</strong></td><td>${t[o.method]}</td><td>${orderStatus(o)}</td><td>${link('/orders/'+o.id,t.details,'text-link','chevron')}</td></tr>`).join('')||emptyRow(6)}</tbody></table></div><div class="table-foot"><span>${rows.length} ${t.rows}</span><span>${t.sample}</span></div></section>`);}
function receipt(o){const t=c();return `<section class="panel"><div class="panel-head"><div><h2>${t.proof}</h2><p>${t.proofDesc}</p></div>${icon('receipt')}</div><div class="receipt-wrap"><div class="receipt">${icon('check')}<h2>${t.transferSuccess}</h2><p class="receipt-note">${t.sampleReceipt}</p><div class="receipt-amount">${money(o.amount)}</div><dl class="metadata"><div><dt>${t.sender}</dt><dd>${o.name}</dd></div><div><dt>${t.recipient}</dt><dd>Taruna Eduka · ${t.account}</dd></div><div><dt>${t.dateTime}</dt><dd>31/10/2026 · 10.12 WIB</dd></div><div><dt>${t.orderCode}</dt><dd>${o.id}</dd></div></dl><div class="stamp">${t.sampleStamp}</div></div></div></section>`;}
function orderPage(o){const t=c();return back('/orders',t.backOrders)+header(t.orderDetails,t.orderDetailDesc)+`<div class="detail-grid"><section class="panel"><div class="order-summary"><div class="badge-line"><h2>${o.id}</h2>${orderStatus(o)}</div><p class="amount">${money(o.amount)}</p><p>${o.product}</p><dl class="metadata"><div><dt>${t.student}</dt><dd>${o.name}</dd></div><div><dt>${t.method}</dt><dd>${t[o.method]}</dd></div><div><dt>${t.created}</dt><dd>31/10/2026 · 10.14 WIB</dd></div><div><dt>${t.paidAmount}</dt><dd>${o.method==='manual'?money(o.amount):'—'}</dd></div>${o.reason?`<div><dt>${t.cancelReason}</dt><dd>${esc(o.reason)}</dd></div>`:''}</dl>${o.method==='gateway'?notice(t.gatewayNote,'section-space'):o.status==='pending'?`<div class="actions">${link('/orders/'+o.id+'/confirm',t.confirmPayment,'button primary','check')}${link('/orders/'+o.id+'/cancel',t.cancelOrder,'button')}</div><p class="section-space">${t.confirmedNote}</p>`:notice(t.finalOrder,'section-space')}</div></section>${o.method==='manual'?receipt(o):`<section class="panel empty">${icon('shield')}<h2>${t.gatewayPending}</h2><p>${t.gatewayNote}</p></section>`}</div>`;}
function decisionPage(o,kind){const t=c();if(o.method!=='manual'||o.status!=='pending')return orderPage(o);const confirm=kind==='confirm';return back('/orders/'+o.id,t.orderDetails)+header(confirm?t.confirmTitle:t.cancelTitle,t.decisionDesc)+`<form class="panel focus-panel" data-form="decision" data-id="${o.id}" data-kind="${confirm?'confirm':'cancel'}" novalidate><div class="panel-head"><h2>${o.id}</h2>${orderStatus(o)}</div><div class="panel-body"><dl class="metadata"><div><dt>${t.student}</dt><dd>${o.name}</dd></div><div><dt>${t.amount}</dt><dd>${money(o.amount)}</dd></div><div><dt>${t.product}</dt><dd>${o.product}</dd></div><div><dt>${t.method}</dt><dd>${t.manual}</dd></div></dl><div class="section-space">${notice(confirm?t.confirmEffect:t.cancelEffect,confirm?'':'warning')}</div>${confirm?`<div class="confirmation"><label><input name="checked" type="checkbox" required>${t.checkConfirm}</label></div>`:`<div class="form-field"><label for="reason">${t.reason}</label><textarea id="reason" name="reason" maxlength="500" required></textarea><small>${t.reasonHint}</small></div>`}<div class="confirmation"><label><input name="fail" type="checkbox">${t.simulateFailure}</label></div><p class="error-text" id="form-error" role="alert"></p><div class="actions section-space">${link('/orders/'+o.id,t.back,'button')}<button class="button ${confirm?'primary':'danger'}" type="submit">${icon(confirm?'check':'alert')}${confirm?t.confirmSimulation:t.cancelSimulation}</button></div></div></form>`;}
function roadmapPage(key){const t=c();const denied=state.role==='operator'&&['programs','users','settings'].includes(key);return header(t[key]||t.overview,t.internal)+`<section class="panel empty">${icon(denied?'shield':'panel')}<h2>${denied?t.accessDenied:t.notAvailable}</h2><p>${denied?t.accessDeniedDesc:t.notAvailableDesc}</p>${link('/dashboard',t.backOverview,'button primary')}</section>`;}
function error(message){const target=document.getElementById('form-error');if(target){target.textContent=message;target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}}
function readDraft(form){const f=new FormData(form);return {name:String(f.get('name')||'').trim(),program:String(f.get('program')||'AKPOL'),columns:Number(f.get('columns')),questions:Number(f.get('questions')),seconds:Number(f.get('seconds'))};}
app.addEventListener('submit',event=>{event.preventDefault();const form=event.target,t=c(),data=new FormData(form);if(form.dataset.form==='session-search'){view.query=String(data.get('query')||'');render();return;}if(form.dataset.form==='order-search'){view.orderQuery=String(data.get('query')||'');render();return;}if(form.dataset.form==='extend'){const n=Number(data.get('minutes')),reason=String(data.get('reason')||'').trim();if(!Number.isInteger(n)||n<1||n>240||!reason||reason.length>500)return error(t.invalidExtension);const s=state.sessions.find(s=>s.id===form.dataset.id);s.extension+=n;s.reason=reason;persist();go('/monitoring/'+s.id,t.extensionSaved);}if(form.dataset.form==='builder'){const d=readDraft(form);if(!d.name||d.name.length>120||!Number.isInteger(d.columns)||d.columns<10||d.columns>50||d.columns%2||!Number.isInteger(d.questions)||d.questions<50||d.questions>100||!Number.isInteger(d.seconds)||d.seconds<1)return error(t.invalidConfig);state.draft=d;persist();if(event.submitter?.value==='preview')go('/kecermatan/preview');else{state.testSaved=false;go('/kecermatan',t.draftSaved);}}if(form.dataset.form==='decision'){const o=state.orders.find(o=>o.id===form.dataset.id);if(!o||o.status!=='pending'||o.method!=='manual')return go('/orders');const confirm=form.dataset.kind==='confirm',reason=String(data.get('reason')||'').trim();if(confirm?!data.get('checked'):!reason||reason.length>500)return error(t.invalidDecision);if(data.get('fail')){form.querySelector('[name="fail"]').checked=false;return error(t.decisionFailure);}o.status=confirm?'confirmed':'cancelled';o.reason=confirm?'':reason;persist();go('/orders/'+o.id,t.decisionSaved);}});
app.addEventListener('change',event=>{const el=event.target;if(el.id==='role')state.role=el.value;else if(el.id==='scenario')state.scenario=el.value;else if(el.id==='session-filter')view.sessionFilter=el.value;else if(el.id==='order-status')view.orderStatus=el.value;else if(el.id==='method-filter')view.method=el.value;else return;noticeText='';render();});
app.addEventListener('input',event=>{const form=event.target.closest('[data-form="builder"]');if(!form)return;const d=readDraft(form);if(Number.isInteger(d.columns)&&Number.isInteger(d.questions)&&Number.isInteger(d.seconds)){for(const [id,val] of [['columns',d.columns],['questions',d.questions],['seconds',d.seconds],['total',d.columns*d.questions]])document.getElementById('summary-'+id).textContent=String(val);}state.draft=d;persist();});
app.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b){if(event.target.closest('a[href^="#/"]')){noticeText='';mobileOpen=false;}return;}const a=b.dataset.action;if(a==='collapse'){state.collapsed=!state.collapsed;render();}if(a==='mobile'){mobileOpen=!mobileOpen;render();if(mobileOpen)document.querySelector('.rail a')?.focus();else document.querySelector('.mobile-toggle')?.focus();}if(a==='theme'){state.theme=state.theme==='light'?'dark':'light';render();}if(a==='locale'){state.lang=state.lang==='id'?'en':'id';render();}if(a==='retry'){state.scenario='normal';render();}if(a==='reset'){const {role,lang,theme}=state;state={...fresh(),role,lang,theme};Object.assign(view,{query:'',sessionFilter:'all',orderQuery:'',orderStatus:'all',method:'all'});persist();go('/dashboard',c().resetDone);}if(a==='save-test'){state.testSaved=true;persist();go('/kecermatan',c().testSaved);}if(a==='sample-choice'){document.querySelectorAll('.answer-key').forEach(e=>{e.setAttribute('aria-pressed',e===b?'true':'false');e.style.background=e===b?'var(--soft)':'';e.style.borderColor=e===b?'var(--accent)':'';});document.getElementById('choice-feedback').textContent=c().choiceSelected+' '+b.dataset.key;}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobileOpen){mobileOpen=false;render();document.querySelector('.mobile-toggle')?.focus();}});
window.addEventListener('hashchange',()=>{mobileOpen=false;render(true);window.scrollTo({top:0,behavior:'instant'});});
if(!location.hash)history.replaceState(null,'','#/dashboard');render();

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.getElementById('main').focus();});
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!mobileOpen)return;const items=[...document.querySelectorAll('.rail a,.rail summary,.rail button')].filter(el=>el.getBoundingClientRect().width>0);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
